def re_arrange_array(arr):
    # Rearrange array so that all negative elements come before positive ones.
    # This function modifies the array in place.
    i = 0
    for j in range(len(arr)):
        if arr[j] < 0:
            arr[i], arr[j] = arr[j], arr[i]
            i += 1

def second_smallest(lst):
    unique_numbers = sorted(set(lst))
    if len(unique_numbers) < 2:
        raise ValueError("List must contain at least two distinct numbers")
    return unique_numbers[1]

import re

def remove_multiple_spaces(s: str) -> str:
    return re.sub(r'\s+', ' ', s)

def is_Two_Alter(s):
    if len(s) < 2:
        return False  # Cannot be two alternating characters if less than 2 chars

    # Extract the two distinct characters expected
    chars = set(s)
    if len(chars) != 2:
        return False

    # Check if characters alternate properly
    for i in range(len(s) - 1):
        if s[i] == s[i + 1]:
            return False

    return True

def max_sub_array_sum(arr):
    max_ending_here = max_so_far = arr[0]
    for x in arr[1:]:
        max_ending_here = max(x, max_ending_here + x)
        max_so_far = max(max_so_far, max_ending_here)
    return max_so_far

